// Берём "текущее время" в момент запуска (работает и от расписания, и от вебхука синхронизации)
const now = new Date();

// входные данные: смены из «Get row(s)3» (вход этой ноды — таблица обедов)
const rows = $('Get row(s)3').all().map(i => i.json);

// телефоны сотрудников, которые сейчас на обеде — их в группы Манго не добавляем
const onLunch = new Set(
  $input.all().map(i => i.json)
    .filter(l => l && l.seg_id && l.status === 'active' && new Date(l.end_utc) > now)
    .map(l => String(l.phone_number))
);

// ✅ ПАРСИМ ВСЁ КАК GMT+3
function parseGmt3(str) {
  const [datePart, timePart] = str.split(' ');
  return new Date(`${datePart}T${timePart}:00+03:00`);
}

// Форматирование в GMT+3
function fmtGmt3(d) {
  return new Intl.DateTimeFormat('ru-RU', {
    timeZone: 'Europe/Moscow',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false
  }).format(d);
}

// фильтрация активных смен (и исключение обедающих)
const active = rows.filter(r => {
  if (!r.date_open || !r.date_close) return false;
  if (onLunch.has(String(r.phone_number))) return false;

  const open = parseGmt3(r.date_open);  // ✅ GMT+3
  const close = parseGmt3(r.date_close); // ✅ GMT+3

  return now >= open && now < close;
});

// возвращаем МАССИВ items (n8n)
return active.map(r => {
  const open = parseGmt3(r.date_open);
  const close = parseGmt3(r.date_close);

  return {
    json: {
      phone_number: r.phone_number,
      name: r.name,
      date_open: r.date_open,
      podrazd: r.podrazdelenie,
      smena: r.smena,

      // 🔍 дебаг
      now_gmt3: fmtGmt3(now),
      open_gmt3: fmtGmt3(open),
      close_gmt3: fmtGmt3(close),
      isActive: now >= open && now < close
    }
  };
});

// Code-нода «Таймер: что изменить» (Run Once for All Items), запускается раз в минуту.
// scheduled → active, когда подошло время; active → returned (overdue), когда вышел лимит.
const now = Date.now();
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (!r || !r.seg_id) continue;
  const start = new Date(r.start_utc).getTime();
  const end = new Date(r.end_utc).getTime();
  if (r.status === 'scheduled' && start <= now) {
    if (end <= now) out.push({ json: { ...r, status: 'cancelled', ended_at: new Date(now).toISOString() } });
    else out.push({ json: { ...r, status: 'active' } });
  } else if (r.status === 'active' && end <= now) {
    out.push({ json: { ...r, status: 'returned', ended_at: new Date(end).toISOString() } });
  }
}
return out;
